"""BicycleCrank_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 2 extrusion(s) and 1 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python BicycleCrank_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector, Vertex
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 50.0    # level along z
z2 = 110.0    # level along z
hole_d = 30.0

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 50.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(0.0, 0.0), P(0.0, 300.0)),
    cf.segment(P(0.0, 300.0), P(50.0, 300.0)),
    cf.segment(P(50.0, 300.0), P(50.0, 0.0)),
    cf.segment(P(50.0, 0.0), P(0.0, 0.0)),
)
part = prism(outline_1, z0, z1)

# ---- 2. extrusion: z 50.0 to 110.0 ------------------------------
outline_2 = cf.wire(
    cf.segment(P(12.5, 12.5), P(37.5, 12.5)),
    cf.segment(P(37.5, 12.5), P(37.5, 37.5)),
    cf.segment(P(37.5, 37.5), P(12.5, 37.5)),
    cf.segment(P(12.5, 37.5), P(12.5, 12.5)),
)
part = part + prism(outline_2, z1, z2)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (25.0, 270.0, hole_d, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

# ---- fillets and chamfers on the edges through these points (edge midpoints) ----------
def edges_at(points):
    es = part.Edges()
    return [min(es, key=lambda e: e.distance(Vertex.makeVertex(*p))) for p in points]

part = part.fillet(10.0, edges_at([
    (12.5, 25.0, 50.0),
    (25.0, 37.5, 50.0),
    (25.0, 12.5, 50.0),
    (37.5, 25.0, 50.0),
]))

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "BicycleCrank_exact.step")
